#' Read a RaCInG simulation output file
#'
#' @param filename Path to a `.out` file generated by [runSim()].
#'
#' @return A list containing the average values, standard deviations, and raw
#'   counts (one slice/row per patient, in file order), and `patients`, the
#'   patient numbers (row indices of the simulated `Cmatrix`) of those slices.
#' @export
Read_Sim_Output <- function(filename) {

  # ------------------------------------------------------------
  # Purpose:
  #   Read simulation output (.out file) for a communication type (D or GSCC)
  #
  # The function parses:
  #   - Metadata
  #   - Raw counts (average + std)
  #   - Composition (average + std)
  #
  # Output format adapts automatically depending on type:
  #   D    → 2D (cell x cell)
  #   GSCC → 1D (cell)
  # ------------------------------------------------------------

  # Read full file
  lines <- utils::read.csv(filename, header = FALSE, stringsAsFactors = FALSE)

  idx <- 1

  # -----------------------------
  # First line: communication type
  # -----------------------------
  communication_type <- as.character(lines[idx, 1])
  idx <- idx + 1

  # -----------------------------
  # Second line: metadata
  # Format: NoPat, N, itNo, av -- only NoPat (patients in this file) is needed here
  # (files written before this was fixed state nrow(Cmatrix) instead, which can
  # be larger; handled by trimming to the patient blocks actually read below)
  # -----------------------------
  meta <- lines[idx, ]
  idx <- idx + 1

  NoPat <- as.integer(meta[1])

  # -----------------------------
  # Determine dimensionality
  # -----------------------------
  if (communication_type == "GSCC") {
    dim_type <- 1
  } else if (communication_type == "D") {
    dim_type <- 2
  } else {
    stop("Unsupported communication type '", communication_type, "' in ", filename,
         ": only D and GSCC are supported (wedges and triangles were removed from RaCInG).", call. = FALSE)
  }

  # Infer number of cells from the cellstring line (line 4). read.csv() pads
  # every row with NA up to the widest row in the file, so ncol() alone would
  # overcount whenever another line (e.g. the 4-field metadata line) is wider
  # than the cellstring line — count only the non-NA entries instead.
  nCells <- sum(!is.na(lines[4, ]))

  # -----------------------------
  # Initialize storage
  # -----------------------------
  if (dim_type == 2) {
    data_a <- array(0, dim = c(nCells, nCells, NoPat))
    data_s <- array(0, dim = c(nCells, nCells, NoPat))
  } else {
    data_a <- array(0, dim = c(nCells, NoPat))
    data_s <- array(0, dim = c(nCells, NoPat))
  }

  raw_count <- matrix(0, nrow = NoPat, ncol = 2)
  patients <- integer(0)
  block_size <- nCells^dim_type

  # -----------------------------
  # Read patient data
  # -----------------------------
  # Each composition block is read as one bulk slice + one vectorized matrix
  # assignment instead of one lines[idx,] subset per row.
  while (idx <= nrow(lines)) {

    p <- as.integer(lines[idx, 1]) # patient ID, the other columns correspond to N and avg
    idx <- idx + 1

    if (is.na(p)) break
    patients <- c(patients, p)
    b <- length(patients) # storage slot: position of this patient's block in the file

    # Skip cell names line
    idx <- idx + 1

    # Raw count
    vals <- lines[idx, ]
    idx <- idx + 1

    raw_count[b, 1] <- as.numeric(vals[2])  # average
    raw_count[b, 2] <- as.numeric(vals[3])  # std

    # Skip "Composition - Average"
    idx <- idx + 1

    avg_block <- as.matrix(lines[idx:(idx + block_size - 1), seq_len(dim_type + 1), drop = FALSE])
    mode(avg_block) <- "numeric"
    idx <- idx + block_size

    # Skip "Composition - Std"
    idx <- idx + 1

    std_block <- as.matrix(lines[idx:(idx + block_size - 1), seq_len(dim_type + 1), drop = FALSE])
    mode(std_block) <- "numeric"
    idx <- idx + block_size

    if (dim_type == 2) {
      data_a[cbind(avg_block[, 1], avg_block[, 2], b)] <- avg_block[, 3]
      data_s[cbind(std_block[, 1], std_block[, 2], b)] <- std_block[, 3]
    } else {
      data_a[cbind(avg_block[, 1], b)] <- avg_block[, 2]
      data_s[cbind(std_block[, 1], b)] <- std_block[, 2]
    }
  }

  # Keep only the slots actually filled (old-format headers can overstate NoPat)
  n_read <- length(patients)
  keep_slices <- function(arr) {
    idx <- rep(list(TRUE), length(dim(arr)) - 1)
    do.call(`[`, c(list(arr), idx, list(seq_len(n_read), drop = FALSE)))
  }
  data_a <- keep_slices(data_a)
  data_s <- keep_slices(data_s)
  raw_count <- raw_count[seq_len(n_read), , drop = FALSE]

  # -----------------------------
  # Return output
  # -----------------------------
  return(list(
    data_avg = data_a,
    data_std = data_s,
    raw_count = raw_count,
    patients = patients
  ))
}

#' Convert raw simulation outputs into feature matrices
#'
#' @param celltypes Character vector of cell-type names.
#' @param patient_names Character vector of patient identifiers: either one per
#'   row of the simulated `Cmatrix` (matched through the patient numbers stored
#'   in the `.out` file, so subset runs get the right names), or exactly one
#'   per patient in the file, in file order.
#' @param communication_type Communication type of the simulation files
#'   (`"D"` or `"GSCC"`).
#' @param remove_direction Logical; if `TRUE`, merge the two directions of each
#'   cell-type pair (direct communication only).
#' @param normalized Logical; if `TRUE`, divide raw values by the uniform
#'   baseline in `sim_norm_file`. Defaults to `TRUE` exactly when
#'   `sim_norm_file` is supplied.
#'   A feature that is zero in both simulations (0/0) is reported as `0`, as in
#'   the kernel method's [calculateDirect()].
#' @param sim_raw_file Path to the raw simulation output file.
#' @param sim_norm_file Optional path to the normalized simulation output file.
#' @param output_folder Directory where the processed CSV files are written.
#' @param file.name Output CSV file name for the means (e.g. `"RaCInG_input.csv"`);
#'   the standard deviations go to the same name with an `_sd` suffix
#'   (`"RaCInG_input_sd.csv"`).
#'
#' @return A list with two patient-by-feature data frames, `mean` and `sd`.
#'   Direct features are named `"Dir_A_B"`, GSCC features `"GSCC_A"`; rows are
#'   named by patient. Patients whose simulation produced no edges are dropped.
#' @export
compute_results_processing <- function(celltypes,
                                       patient_names,
                                       communication_type,
                                       remove_direction = TRUE,
                                       normalized = !is.null(sim_norm_file),
                                       sim_raw_file = NULL, sim_norm_file = NULL,
                                       output_folder = NULL, file.name = NULL) {

  # -----------------------------
  nCells <- length(celltypes)  # number of cell types

  # -----------------------------
  # Read simulation outputs
  # -----------------------------
  # data_raw  : non-normalized simulation
  # data_norm : normalized (uniform) simulation
  data_raw  <- Read_Sim_Output(sim_raw_file)
  if (normalized) data_norm <- Read_Sim_Output(sim_norm_file)

  pat_ids <- data_raw$patients
  if (normalized && !identical(data_norm$patients, pat_ids)) {
    stop("sim_raw_file and sim_norm_file contain different patients.", call. = FALSE)
  }
  if (length(pat_ids) > 0 && length(patient_names) >= max(pat_ids)) {
    patient_names <- patient_names[pat_ids]
  } else if (length(patient_names) != length(pat_ids)) {
    stop("patient_names must have one name per row of the simulated Cmatrix, or one per ",
         "patient in the simulation file (", length(pat_ids), ").", call. = FALSE)
  }

  # Extract arrays of averages and patient-level raw counts and stds
  av      <- data_raw$data_avg
  av_sd   <- data_raw$data_std
  summary <- data_raw$raw_count
  if (normalized) {
    avN     <- data_norm$data_avg
    avN_sd  <- data_norm$data_std
    summaryN <- data_norm$raw_count
  } else {
    avN <- NULL
    avN_sd <- NULL
    summaryN <- NULL
  }

  # -----------------------------
  # Convert arrays -> labeled [patient x interaction] matrices directly via a
  # single reshape instead of building one named-list entry per interaction
  # then converting to a data.frame.
  #
  # Labels are plain cell-type combinations here (no type prefix) so the
  # remove_direction merging below keeps working unchanged; the "Dir_"/"GSCC_"
  # prefix is added once, at the very end, after bundling/normalization.
  .array_to_labeled_matrix <- function(arr, celltypes) {
    d <- dim(arr)
    dim_type <- length(d) - 1
    nCells <- d[1]
    NoPat <- d[length(d)]
    out <- t(matrix(arr, nrow = nCells^dim_type, ncol = NoPat))
    if (dim_type == 1) {
      labels <- celltypes
    } else {
      grid <- do.call(expand.grid, rep(list(seq_len(nCells)), dim_type))
      labels <- do.call(paste, c(lapply(grid, function(idx) celltypes[idx]), list(sep = "_")))
    }
    colnames(out) <- labels
    out
  }

  # The index grid driving column order in .array_to_labeled_matrix() above
  # (needed again below to group columns for remove_direction by *index*,
  # not by parsing back the pasted labels -- cell-type names can themselves
  # contain "_", e.g. multideconv's method-tagged names like
  # "CBSX_CBSX.HNSCC.scRNAseq_B.cells", so splitting a label such as
  # "A_B_CBSX_CBSX.HNSCC.scRNAseq_B.cells" on "_" cannot tell which
  # underscores separate cell types from underscores inside one cell-type's
  # own name -- silently scrambling which columns get merged together).
  dim_type <- length(dim(av)) - 1
  index_grid <- if (dim_type > 1) do.call(expand.grid, rep(list(seq_len(nCells)), dim_type)) else NULL

  av    <- .array_to_labeled_matrix(av, celltypes)
  av_sd <- .array_to_labeled_matrix(av_sd, celltypes)
  if (normalized) {
    avN    <- .array_to_labeled_matrix(avN, celltypes)
    avN_sd <- .array_to_labeled_matrix(avN_sd, celltypes)
  }

  # -----------------------------
  # Remove direction (merge labels)
  # -----------------------------
  # Merge A->B and B->A into one A_B feature. Grouping is computed from
  # index_grid's integer columns (never ambiguous, unlike re-splitting the
  # pasted string labels -- see note above), then rowsum() (a single
  # vectorized grouped-sum) does the actual merge.
  if (remove_direction && dim_type > 1) {
    new_labels <- vapply(seq_len(nrow(index_grid)), function(r) {
      paste(sort(as.integer(index_grid[r, ])), collapse = "_")
    }, character(1))

    av <- t(rowsum(t(av), group = new_labels))
    if (normalized) avN <- t(rowsum(t(avN), group = new_labels))
    # merge variances (sum variances when summing counts), then convert back to sd
    av_sd <- sqrt(t(rowsum(t(av_sd^2), group = new_labels)))
    if (normalized) avN_sd <- sqrt(t(rowsum(t(avN_sd^2), group = new_labels)))

    # rowsum() leaves the index-based group keys (e.g. "1_2_3") as column
    # names; convert back to real cell-type-name labels now that grouping is
    # done -- safe to split on "_" here since these keys are our own
    # small-integer strings, never real (possibly "_"-containing) cell-type names.
    .relabel_from_index_keys <- function(mat) {
      idx_keys <- strsplit(colnames(mat), "_")
      colnames(mat) <- vapply(idx_keys, function(idx) {
        paste(celltypes[as.integer(idx)], collapse = "_")
      }, character(1))
      mat
    }
    av    <- .relabel_from_index_keys(av)
    av_sd <- .relabel_from_index_keys(av_sd)
    if (normalized) {
      avN    <- .relabel_from_index_keys(avN)
      avN_sd <- .relabel_from_index_keys(avN_sd)
    }
  }

  # -----------------------------
  # Normalization
  # -----------------------------
  # Perform normalization only when requested. If not normalizing, use raw counts.
  if (normalized) {
    # 0/0 (no communication observed in either simulation) -> 0, matching the
    # kernel method; the original Python set these to 1.
    zero_idx <- which(av == 0 & avN == 0, arr.ind = TRUE)
    if (nrow(zero_idx) > 0) {
      avN[zero_idx] <- 1
      if (!is.null(av_sd))  av_sd[zero_idx]  <- 0
      if (!is.null(avN_sd)) avN_sd[zero_idx] <- 0
    }

    # Replace any remaining zeros in baseline to 1 (to prevent division errors)
    avN_zero_before <- avN == 0
    avN[avN == 0] <- 1
    if (!is.null(avN_sd)) avN_sd[avN_zero_before] <- 0

    # Normalize counts: divide non-uniform by uniform counts
    Norm_mean <- av / avN

    # propagate sd using delta method (assumes independence)
    av_var  <- (av_sd)^2
    avN_var <- (avN_sd)^2
    # guard if sd matrices are NULL (shouldn't be, but safe)
    if (is.null(av_sd))  av_var <- matrix(0, nrow = nrow(av), ncol = ncol(av))
    if (is.null(avN_sd)) avN_var <- matrix(0, nrow = nrow(avN), ncol = ncol(avN))
    # Var(X/Y) ≈ Var(X)/μY^2 + μX^2 * Var(Y) / μY^4
    Norm_var <- (av_var / (avN^2)) + ((av^2) * avN_var / (avN^4))
    Norm_sd  <- sqrt(Norm_var)
  } else {
    # Skip normalization and use raw counts
    Norm_mean <- av
    Norm_sd   <- av_sd
  }

  # -----------------------------
  # Remove patients where simulation failed
  # -----------------------------
  # Patients with zero total counts in raw or baseline simulations are excluded
  # because they indicate failed or empty simulations.
  if (normalized && !is.null(summaryN)) {
    delete_indices <- unique(c(which(summary[,1] == 0), which(summaryN[,1] == 0)))
  } else {
    delete_indices <- which(summary[,1] == 0)
  }

  if (length(delete_indices) > 0) {
    Norm_mean <- Norm_mean[-delete_indices, , drop = FALSE]
    Norm_sd   <- Norm_sd[-delete_indices, , drop = FALSE]
    patients <- patient_names[-delete_indices]
  } else {
    patients <- patient_names
  }

  # -----------------------------
  # Convert normalized data to dataframe (means + sd)
  # -----------------------------
  # Prefix columns ("Dir_A_B", "GSCC_A"); direct features use the same naming
  # as compute_racing_kernel()'s ("Dir_" + lower-index cell type first).
  feature_prefix <- if (communication_type == "D") "Dir" else communication_type
  colnames(Norm_mean) <- paste0(feature_prefix, "_", colnames(Norm_mean))
  colnames(Norm_sd)   <- paste0(feature_prefix, "_", colnames(Norm_sd))

  df_mean <- as.data.frame(Norm_mean)
  rownames(df_mean) <- patients
  df_sd_out <- as.data.frame(Norm_sd)
  rownames(df_sd_out) <- patients

  # -----------------------------
  # Save CSVs
  # -----------------------------
  utils::write.csv(df_mean, file = file.path(output_folder, file.name), row.names = TRUE)
  sd_file <- paste0(sub("\\.csv$", "", file.name), "_sd.csv")
  utils::write.csv(df_sd_out, file = file.path(output_folder, sd_file), row.names = TRUE)

  return(list(mean = df_mean, sd = df_sd_out))
}